module serial2parallel (
    input clk, 
    input rst_n, 
    input din_serial, 
    input din_valid, 
    output reg [7:0] dout_parallel, 
    output reg dout_valid
);
// Sequential logic block triggered on the positive edge of the clock or negative edge of the reset signal
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        // Initialize the counter to 0 when reset is active
        dout_parallel <= 8'd0;
        dout_valid <= 1'b0;
    end else begin
        // Update the parallel output data based on the current value of the counter
        dout_parallel[dout_parallel[3:0]] <= din_serial;
        dout_valid <= (dout_parallel[3:0] == 4'd7 && din_valid == 1'b1) ? 1'b1 : 1'b0;
    end
end
endmodule
